class MinStack:
    def __init__(self):
        self.stack = []

    def push(self, val):
        if not self.stack:
            self.stack.append((val, val))
        else:
            self.stack.append((val, min(val, self.stack[-1][1])))

    def pop(self):
        self.stack.pop()

    def top(self):
        return self.stack[-1][0]

    def getMin(self):
        return self.stack[-1][1]

def first_missing(nums):
    n = len(nums)

    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n+1

    for i in range(n):
        val = abs(nums[i])
        if 1 <= val <= n:
            nums[val-1] = -abs(nums[val-1])

    for i in range(n):
        if nums[i] > 0:
            return i+1

    return n+1

